import json,subprocess,html,hashlib
from pathlib import Path
R=Path(__file__).resolve().parents[1];E=R/'evidence-v16'
def read(n):return json.loads((E/n).read_text())
def write(n,x):(E/n).write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
checks=read('browser-checks.json');cross=read('browser-crossings.json');capture=read('capture-run.json');cold=read('blender-cold.json');assert not checks['errors'] and not capture['errors'];assert len(checks['entries'])==2 and capture['frames']==40
probes=[]
for row in capture['videos']:
 p=E/row['file'];v=json.loads(subprocess.check_output(['ffprobe','-v','error','-show_format','-show_streams','-of','json',str(p)]));probes.append({'file':row['file'],'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'format':v['format'],'streams':v['streams']})
write('video-probes.json',{'requested_wall_seconds':6,'note':'Actual encoded duration and frame rate below; CPU renderer timing is not device performance validation.','entries':probes})
summary={'version':'0.16.0','scope':'Run hand shape and garment clearance on two native humanoid bodies; old leg/root/skirt motion and six other clips preserved','programmatic':'passed; pins, native/GLB preservation, cold export, structure','blender_offline':'cold-open evaluated surface and native actions passed; no offline art render','browser_actual':'Chromium SwiftShader load, playback, controls, A/B views and 120Hz bounded crossings passed','physical_mobile':'not-tested; 390px browser viewport only','human_art':'not-tested','godot_and_maps':'not-tested this version','art_approved':False,'game_ready':False,'browser':checks['entries'],'blender':cold['entries'],'crossings':[{'key':r['key'],'variants':[{k:v for k,v in x.items() if k!='samples'} for x in r['variants']]} for r in cross['entries']],'frames':capture['frames'],'videos':[{'file':p['file'],'encoded_duration_s':p['format'].get('duration')} for p in probes],'limitations':['Original stylized bodies/clothing patterns retained; not realistic-body refit.','Upper-arm abduction now follows a body-specific clothing clearance envelope. Elbows retain the prior near-constant 62.5-degree Run bend; natural upper-arm/forearm variation is still a separate task.','Run hand and upper-arm clearance only; no new transition from Walk to Run.','Full sleeves/body/garment collision, solid containment, cloth thickness, phone hardware and human art review remain untested.','Upstream .vroid project unavailable; original VRM and editable Blender derivatives included.']};write('acceptance-summary.json',summary)
frames=read('frame-catalog.json');parts=['<!doctype html><html lang="zh-Hant"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>V16 雙身形跑步手型證據</title><style>body{font:16px system-ui;max-width:1250px;margin:30px auto;padding:15px;background:#f4f6f2;color:#163e35}img{width:48%;margin:.5%}video{width:48%}a{color:#126a58}h2{margin-top:36px}</style><h1>V16 跑步手型前後比較</h1><p>A：Vivi 0.3／Vita 0.2；B：Vivi 0.4／Vita 0.3。實際瀏覽器、同鏡位、同時間；全部待人工美術驗收。</p><p><a href="../web-v16/">開啟互動驗收場</a> · <a href="acceptance-summary.json">完整狀態</a> · <a href="video-probes.json">錄影實際長度</a></p>']
for v in capture['videos']:parts.append('<video controls loop muted src="'+v['file']+'"></video>')
for sequence in frames['sequences']:
 parts.append('<h2>'+html.escape(sequence['key']+' · '+sequence['view'])+'</h2>')
 for frame in sequence['frames']:parts.append('<a href="'+frame['file']+'"><img loading="lazy" src="'+frame['file']+'" alt="'+str(frame['time_s'])+' 秒"></a>')
(E/'index.html').write_text(''.join(parts)+'</html>');print('V16_EVIDENCE_READY')
